function repository<R extends object>(facts:Partial<R>,calls:string[]):R{return new Proxy(facts,{get(target,key){if(key==='then')return undefined;if(key in target)return target[key as keyof R];if(typeof key==='string'&&/^(prepare|guard|lock)/.test(key))return (...args:unknown[])=>{calls.push(key+':'+JSON.stringify(args));return key;};return ()=>{throw Error('Unexpected fact '+String(key));};}})as R;}
function commands(calls:string[]){return {async replay<Result=Record<string,unknown>>():Promise<Result|null>{calls.push('replay');return null;},async commit<Result>(_actor:StaffActor,_key:string,op:string,_input:unknown,_id:string,_version:number,result:Result,effects:string[],scope?:Pick<StaffActor,'companyId'|'branchId'|'departmentId'>){calls.push('commit:'+op+':'+effects.join(',')+':'+JSON.stringify(scope));return result;}};}
function common(calls:string[]){return {clock:{now:()=>Date.parse('2026-10-06T00:00:00Z')},commands:commands(calls),getProject:async()=>({...project}),activeStaff:async(_company:string,userId:string)=>{calls.push('staff:'+userId);return {...staff,user_id:userId};},staffGuard:(_key:string,_company:string,userId:string,suffix?:string)=>'staff:'+userId+':'+(suffix??''),requirePermission:(a:WorkContext,p:string)=>{calls.push(p);return a;}};}
