 test('deduplicates members and stages owner/member fences with the current staff scope',async()=>{const f=brief();await f.app.saveProject(actor,null,projectSchema.parse({title:'Concrete delivery',memberUserIds:['member','member']}),'key');expect(f.calls.filter(c=>c==='staff:member')).toHaveLength(1);expect(f.calls.at(-1)).toContain('commit:project.create:staff:owner:,prepareProject,prepareMemberReplacement,staff:member:member-0,prepareMember:');expect(f.calls.at(-1)).toContain('"branchId":"branch"');});
 test('receipt replay happens before current staff or project reads',async()=>{const f=brief();f.ports.commands.replay=async<Result>()=>({id:'existing',version:2}as Result);expect(await f.app.saveProject(actor,'project',projectSchema.parse({title:'Replay retained'}),'key')).toEqual({id:'existing',version:2});expect(f.calls).toEqual([]);});
 test('another member cannot replace the owner brief',async()=>{const f=brief();await expect(f.app.saveProject({...actor,userId:'member'},'project',projectSchema.parse({title:'Forbidden edit'}),'key')).rejects.toMatchObject({code:'PROJECT_OWNER_REQUIRED'});expect(f.calls.some(c=>c.startsWith('prepare'))).toBe(false);});
 test('issued handoff freezes membership before querying proposed new members',async()=>{const f=brief({visibleProject:async()=>({...project,lifecycle_status:'handoff_pending'})});await expect(f.app.saveProject(actor,'project',projectSchema.parse({title:'Frozen brief',memberUserIds:['new-member']}),'key')).rejects.toMatchObject({code:'PROJECT_STRUCTURE_FROZEN'});expect(f.calls).not.toContain('staff:new-member');});
 test('missing current visible project keeps the existing 404 behavior',async()=>{const f=brief({visibleProject:async()=>null});await expect(f.app.getProject(actor,'missing')).rejects.toMatchObject({status:404,code:'PROJECT_NOT_FOUND'});});
