  const draining=render(projectControls(false,true));for(const label of ['Delivery','Complete','Start','Cancel'])expect(draining).toContain(label);for(const label of ['Add a milestone','Reopen','>Edit<'])expect(draining).not.toContain(label);
  const retained=render(projectControls(false,false));expect(retained).toContain('Delivery');for(const label of ['Add a milestone','>Complete<','>Start<','>Cancel<','Reopen','>Edit<'])expect(retained).not.toContain(label);
