function projectClient<Props>(node:ReactNode,type:ReactElement['type']):ReactElement<Props>|undefined{
 if(Array.isArray(node)){for(const child of node){const found=projectClient<Props>(child,type);if(found)return found;}return;}
 if(isValidElement<Props>(node)&&node.type===type)return node;
 return isValidElement<{children?:ReactNode}>(node)?projectClient<Props>(node.props.children,type):undefined;
}
